import {BroadcastMotion} from './motion.js';
import {newProject,newSlide,normalizeProject,validateProject,DEFAULT_SETTINGS,LABELS,labelsFor,cornerColors,RoundEngine,countdownSource,resultText,hideMysteryContent,clone,uid,shuffled,safeMedia} from './core.js';
import {escapeHTML as e,icon,graphic} from './content.js';
import {exportStandalone} from './export.js';
import {SoundDesk} from './audio.js';
import {saveProject,listProjects,deleteProject,mediaData} from './storage.js';

const root=document.getElementById('app'),modal=document.getElementById('modal');
let project=newProject(),view='home',selected=0,target='prompt',playIndex=0,focus=false,playingAudio=false,recent=[],saveTimer,toastTimer,saveSequence=0,unsaved=false;
let undoStack=[],redoStack=[],assetTab='library',assetTarget='prompt',pendingCue='',dragIndex=-1,modalKind='',saveQueue=Promise.resolve();
const modes={knowledge:'Question challenge',prediction:'Mystery reveal',roulette:'Random corner'};
const sound=new SoundDesk(toast);
const stageMotion=new BroadcastMotion();
const engine=new RoundEngine({
 onState(state){if(view!=='play')return;if(['locked','paused','revealed','idle'].includes(state))sound.stopEffects();if(state==='locked')stopVideo();renderControls();const kicker=root.querySelector('.prompt-kicker');if(kicker)kicker.textContent=state==='counting'?'Choose your corner':state==='locked'?'Choices locked':state==='revealing'?'Here it comes…':modes[currentPlay()?.mode]||'';},
 onTick(seconds,ratio){updateClock(seconds,ratio);},
 onSound(type){if(['tick','lock'].includes(type)&&countdownSource(project,playIndex))return;if(type==='suspense'&&project.audio.drumroll){sound.custom(project.audio.drumroll);return;}sound.effect(type);},
 onSpin(index){root.querySelectorAll('.player .corner').forEach((el,i)=>el.classList.toggle('spinning',i===index));},
 onReveal(winner){if(view!=='play')return;sound.stopEffects();renderPlayerStage();renderControls();const out=project.rules==='out';const cue=project.audio[out?'sad':'happy'];if(cue)sound.custom(cue);else sound.effect(out?'out':'safe');if(currentPlay().mode==='prediction'&&hasAudio(currentPlay()))playCue();}
});
const current=()=>project.slides[selected],currentPlay=()=>project.slides[playIndex];
const hasAudio=s=>s?.centerType==='audio'&&!!(s.centerContent||s.sound);
const motionReduced=()=>project.settings.reducedMotion||window.matchMedia('(prefers-reduced-motion: reduce)').matches;
const button=(action,label,ic='',cls='',attrs='')=>`<button type="button" class="btn ${cls}" data-action="${action}" aria-label="${e(label)}" ${attrs}>${ic?icon(ic):''}<span class="btn-label">${label}</span></button>`;
const iconButton=(action,label,ic,attrs='')=>`<button type="button" class="btn icon-only ghost" data-action="${action}" aria-label="${e(label)}" title="${e(label)}" ${attrs}>${icon(ic)}</button>`;
const brand=()=>`<button class="brand" type="button" data-action="home" aria-label="Four Corners home"><span class="logo-mark" aria-hidden="true"><i></i><i></i><i></i><i></i></span><span><small>MR. DREW’S</small><strong>FOUR CORNERS <em>STUDIO</em></strong></span></button>`;
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),4500);}
let fitFrame=0;
function scheduleFit(){cancelAnimationFrame(fitFrame);fitFrame=requestAnimationFrame(fitStage);}
function fitStage(){
 const stage=root.querySelector('.stage');if(!stage)return;
 const question=stage.querySelector('.question');if(question){question.style.fontSize='';let size=parseFloat(getComputedStyle(question).fontSize);const limit=view==='play'?Math.max(64,stage.clientHeight*.25):100;while(question.scrollHeight>limit&&size>17){size-=1;question.style.fontSize=size+'px';}}
 stage.querySelectorAll('.corner').forEach(corner=>{
   const content=corner.querySelector('.corner-content'),answer=corner.querySelector('.answer'),media=corner.querySelector('.corner-media');
   if(!content||content.clientHeight<10)return;
   if(answer){answer.style.fontSize='';let size=parseFloat(getComputedStyle(answer).fontSize);const reserve=media?Math.min(60,content.clientHeight*.4):0;while((answer.scrollHeight>content.clientHeight-reserve||answer.scrollWidth>content.clientWidth+2)&&size>(view==='play'?16:13)){size-=1;answer.style.fontSize=size+'px';}}
   if(media){const available=Math.max(1,content.clientHeight-(answer?answer.offsetHeight+8:0));media.style.maxHeight=available+'px';const art=media.querySelector('img,svg');if(art)art.style.maxHeight=available+'px';}
 });
}
window.addEventListener('resize',scheduleFit);
root.addEventListener('load',ev=>{if(ev.target.tagName==='IMG')scheduleFit();},true);
function saveStatus(text,error=false){const el=document.getElementById('save-status');if(el){el.textContent=text;el.classList.toggle('error',error);}}
function remember(){undoStack.push(clone(project));if(undoStack.length>25)undoStack.shift();redoStack=[];updateUndo();}
function updateUndo(){for(const action of ['undo','redo']){const b=root.querySelector(`[data-action="${action}"]`);if(b)b.disabled=!(action==='undo'?undoStack:redoStack).length;}}
function changed(){project.updatedAt=Date.now();unsaved=true;saveStatus('Saving…');clearTimeout(saveTimer);saveTimer=setTimeout(()=>persist(),600);}
function persist(){clearTimeout(saveTimer);const snapshot=clone(project),seq=++saveSequence;saveQueue=saveQueue.catch(()=>{}).then(()=>saveProject(snapshot));return saveQueue.then(()=>{if(seq===saveSequence&&project.id===snapshot.id&&project.updatedAt===snapshot.updatedAt){unsaved=false;saveStatus('Saved on this device');}return true;}).catch(()=>{saveStatus('Export to keep this game',true);toast('Automatic saving is unavailable or storage is full. Export your .4cr file to keep your work.');return false;});}
async function loadRecent(){try{recent=await listProjects();}catch{recent=[];}if(view==='home')renderHome();}
async function goHome(){stageMotion.cancel();if(view!=='home')await persist();engine.stop();sound.stopAll();view='home';modal.close();await loadRecent();renderHome();}
function openProject(p){stageMotion.cancel();engine.stop();sound.stopAll();project=p;selected=0;target='prompt';undoStack=[];redoStack=[];view='edit';changed();renderEditor();}
function renderHome(){root.innerHTML=`<main class="home"><header class="app-header">${brand()}<div class="header-actions"><span class="credit">Created by Drew Wichman</span>${button('help','How to play','help','ghost')}</div></header><div class="home-content"><section class="hero"><div class="hero-left"><div class="eyebrow">Your game. Your content.</div><h1 class="hero-title">FOUR<span>CORNERS</span></h1><p class="hero-copy">Start with a blank game. Add your own questions, pictures, and audio. Export a finished game that plays on its own.</p><div class="hero-buttons">${button('new','Create a game','plus','primary')}</div><div class="hero-link">${button('import','Open a .4cr game','folder','ghost')}</div></div></section>${recent.length?`<div class="section-title"><h2>Your saved games</h2><span>On this browser</span></div><section class="recent-list">${recent.slice(0,12).map(r=>`<div class="recent-card"><button type="button" data-action="recent" data-id="${e(r.id)}"><strong>${e(r.name)}</strong><small>${r.project.slides.length} rounds · ${new Date(r.updatedAt).toLocaleDateString(undefined,{month:'short',day:'numeric'})}</small></button>${iconButton('delete-saved','Delete saved game','trash',`data-id="${e(r.id)}"`)}</div>`).join('')}</section>`:''}<footer class="home-footer"><span>Created by Drew Wichman</span><span>Create · Play · Export standalone</span></footer></div></main>`;}
function renderEditor(){root.innerHTML=`<main class="studio"><header class="app-header"><div class="header-title">${brand()}<span class="header-divider"></span><input class="game-title-input" data-project="name" aria-label="Game name" maxlength="120" value="${e(project.name)}"><span id="save-status" class="save-status">${unsaved?'Saving…':'Saved on this device'}</span></div><div class="header-actions">${iconButton('undo','Undo (Ctrl Z)','undo')}${iconButton('redo','Redo (Ctrl Shift Z)','redo')}${button('import','Open','folder','ghost')}${button('export','Export','save')}${button('play','Play','play','primary')}</div></header><div class="studio-grid"><aside class="round-rail"><div class="rail-top"><h2>Rounds <span class="muted">${project.slides.length}</span></h2>${iconButton('shuffle','Shuffle rounds','shuffle')}</div><div class="round-list" id="round-list" aria-label="Rounds"></div><div class="rail-bottom">${button('add','Add','plus')}${button('duplicate','Copy','copy')}</div></aside><section class="workspace"><div class="workspace-bar"><span class="eyebrow">Stage preview · Round ${selected+1}</span><div class="row">${button('preview-round','Try this round','play','small ghost')}${iconButton('settings','Game settings','settings')}</div></div><div class="editor-preview" id="editor-preview"></div><p class="preview-caption">Click the question or a corner to edit it. Your changes appear right here.</p><div class="studio-bottom"><div class="row">${button('settings','Game settings','settings','small')}${button('print','Corner signs','print','small ghost')}</div><div class="row">${iconButton('move-up','Move round earlier','up')}${iconButton('move-down','Move round later','down')}${iconButton('delete-round','Delete round','trash')}</div></div></section><aside class="inspector" id="inspector"></aside></div></main>`;renderRail();renderEditorPreview();renderInspector();updateUndo();}
function renderRail(){const el=document.getElementById('round-list');if(!el)return;el.innerHTML=project.slides.map((s,i)=>`<button type="button" class="slide-thumb ${selected===i?'selected':''}" draggable="true" data-action="select-round" data-index="${i}" aria-label="Edit round ${i+1}: ${e(s.question||'Untitled round')}" ${selected===i?'aria-current="true"':''}><span class="thumb-title"><span>ROUND ${String(i+1).padStart(2,'0')}</span>${s.mode==='roulette'?icon('shuffle'):s.mode==='prediction'?icon('eye'):''}</span><span class="thumb-stage" aria-hidden="true"><span></span><span></span><span></span><span></span></span><span class="thumb-question">${e(s.question||'Your next question…')}</span></button>`).join('');}
function promptMarkup(s,edit){const hidden=hideMysteryContent(s,engine.state,edit);const audio=hasAudio(s);let media='';if(hidden){media='<div class="mystery-orb" aria-label="Hidden until the reveal">?</div>';}else if(s.centerType==='graphic'&&s.graphic){media=graphic(s.graphic);}else if(s.centerType==='image'&&s.centerContent){media=`<img src="${e(s.centerContent)}" alt="Question picture">`;}else if(s.centerType==='video'&&s.centerContent){media=edit?`${icon('play')} Video`:`<video src="${e(s.centerContent)}" controls playsinline preload="metadata" aria-label="Question video"></video>`;}else if(audio){media=edit?`<span class="listen-button">${icon('headphones')} Listening round</span>`:`<button type="button" class="listen-button ${playingAudio?'is-playing':''}" data-action="cue"><span class="sound-bars" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i></span><span>${playingAudio?'Stop audio':'Play audio'}</span></button>`;}else if(s.centerType==='text'&&s.centerContent){media='';}
 const question=s.question|| (s.mode==='roulette'?'Choose your corner!':edit?'Write your question…':'Choose your corner.');return `<div class="prompt ${edit&&target==='prompt'?'active-target':''}" ${edit?'data-action="target" data-target="prompt" role="button" tabindex="0" aria-label="Edit the question"':''}><div class="prompt-copy"><div class="round-index">Round ${String(edit?selected+1:playIndex+1).padStart(2,'0')}</div><div class="prompt-kicker">${edit?modes[s.mode]:hidden?'Make your prediction':modes[s.mode]}</div><h2 class="question">${e(question)}</h2>${!hidden&&s.centerType==='text'&&s.centerContent?`<p class="prompt-subtext">${e(s.centerContent)}</p>`:''}</div>${media?`<div class="prompt-media">${media}</div>`:''}</div>`;}
function clockMarkup(){return `<div class="scoreboard" role="timer" aria-label="${project.settings.seconds} seconds remaining" style="--progress:100%"><span class="clock-number">${project.settings.seconds}</span><span class="clock-unit">Seconds</span><span class="clock-track" aria-hidden="true"><i></i></span></div>`;}
function updateClock(seconds,ratio,state=engine.state){
 const clock=root.querySelector('.scoreboard');if(!clock)return;
 const label={paused:'Paused',locked:'Time’s up',revealing:'Revealing',revealed:'Revealed'}[state]||'Seconds';
 clock.style.setProperty('--progress',`${Math.max(0,Math.min(1,ratio))*100}%`);
 clock.querySelector('.clock-number').textContent=seconds;
 clock.querySelector('.clock-unit').textContent=label;
 clock.classList.toggle('urgent',state==='counting'&&seconds>0&&seconds<=3);
 clock.dataset.state=state;
 clock.setAttribute('aria-label',`${seconds} seconds remaining${label==='Seconds'?'':', '+label}`);
}
function stageMarkup(s,edit=false){return `<section class="stage sports-stage ${project.labels==='colors'?'color-labels':''} ${project.settings.largeText?'large-text':''} ${motionReduced()?'reduced-motion':''} ${!edit&&focus?'focus-prompt':''} ${!edit&&engine.state==='revealed'?'broadcast-reveal':''}" aria-label="Four Corners stage"><div class="stage-heading">${clockMarkup()}${promptMarkup(s,edit)}</div><div class="board">${s.corners.map((c,i)=>{const won=!edit&&engine.state==='revealed'&&engine.winner===i;const dim=!edit&&engine.state==='revealed'&&!won;const visual=c.image?`<img src="${e(c.image)}" alt="Corner ${e(labelsFor(project)[i])} picture">`:graphic(c.graphic);const tag=edit?'button':'div';const empty=!visual&&!c.text;return `<${tag} ${edit?'type="button" data-action="target" data-target="'+i+'"':''} class="corner ${edit&&target===i?'active-target':''} ${won?'selected-result':''} ${won&&project.rules==='out'?'out-result':''} ${dim?'dimmed':''}" data-corner="${i}" style="--corner:${cornerColors(project)[i]}" ${edit?`aria-label="Edit corner ${i+1}"`:''}><span class="corner-top"><span class="corner-label">${e(labelsFor(project)[i])}</span>${edit&&c.isCorrect&&s.mode!=='roulette'?'<span class="corner-result-label">✓ Correct</span>':`<span class="corner-word">Corner ${i+1}</span>`}</span><span class="corner-content">${visual?`<span class="corner-media ${!c.image&&['note','rhythm','dynamic'].includes(c.graphic?.kind)?'sheet':''}">${visual}</span>`:''}${c.text?`<span class="answer ${c.text.length>80?'long':c.text.length>28?'medium':''}">${e(c.text)}</span>`:''}${empty?`<span class="${edit&&s.mode!=='roulette'?'answer muted':'corner-number-hero'}">${edit&&s.mode!=='roulette'?'Add a choice':e(labelsFor(project)[i])}</span>`:''}</span>${won?`<span class="reveal-banner"><span class="reveal-banner-inner">${icon(project.rules==='out'?'close':'check')}<strong>${project.rules==='out'?'Out!':project.rules==='safe'?'Safe!':s.mode==='roulette'?'Selected!':'Correct!'}</strong><small>Corner ${e(labelsFor(project)[i])}</small></span></span>`:''}</${tag}>`;}).join('')}</div></section>`;}
function renderEditorPreview(){const el=document.getElementById('editor-preview');if(el){el.innerHTML=stageMarkup(current(),true);scheduleFit();}}
function field(label,html,hint=''){return `<label class="field"><span>${label}</span>${html}${hint?`<small>${hint}</small>`:''}</label>`;}
function select(options,value,attrs){return `<select ${attrs}>${options.map(([v,l])=>`<option value="${v}" ${value===v?'selected':''}>${l}</option>`).join('')}</select>`;}
function renderInspector(){const el=document.getElementById('inspector');if(!el)return;const s=current();const tabs=`<div class="inspector-tabs" aria-label="Edit area"><button type="button" class="${target==='prompt'?'active':''}" data-action="target" data-target="prompt">Prompt</button>${[0,1,2,3].map(i=>`<button type="button" class="${target===i?'active':''}" data-action="target" data-target="${i}">${i+1}</button>`).join('')}</div>`;
 if(target==='prompt'){let content='';if(s.centerType==='text')content=field('Supporting text',`<textarea data-slide="centerContent" rows="2" maxlength="1000" placeholder="An optional clue or instruction">${e(s.centerContent)}</textarea>`);else if(s.centerType==='audio'){content=`<button type="button" class="media-drop" data-action="upload">${icon('headphones')} ${s.centerContent?'Audio added — replace':s.sound?'Built-in rhythm — replace':'Add your audio file'}</button><div class="media-tools">${button('assets','My media','folder','small')}${s.centerContent||s.sound?button('editor-cue','Listen','play','small'):''}</div>${s.sound?field('Tempo (BPM)',`<input type="number" min="40" max="200" value="${s.sound.tempo}" data-sound="tempo">`):''}${s.centerContent?`<div class="row" style="margin-top:16px;align-items:flex-start">${field('Start (sec)',`<input type="number" min="0" step="0.1" value="${s.clip.start}" data-clip="start">`)}${field('End (sec)',`<input type="number" min="0" step="0.1" value="${s.clip.end}" data-clip="end">`)}</div><p class="inspector-subtitle">End at 0 plays to the end of the file.</p>`:''}`;}else{content=`<button type="button" class="media-drop" data-action="${'upload'}">${s.centerType==='graphic'&&s.graphic?graphic(s.graphic):s.centerType==='image'&&s.centerContent?`<img src="${e(s.centerContent)}" alt="Current prompt picture">`:`${icon(s.centerType==='video'?'play':'image')} ${s.centerType==='graphic'?'Choose a visual card':s.centerContent?'Media added — replace':'Upload or paste media'}`}</button><div class="media-tools">${button('assets','My media','folder','small')}${button('media-url','Use a URL','','small ghost')}</div>`;}
 el.innerHTML=`${tabs}<div class="eyebrow">Round ${selected+1}</div><h2>The question</h2>${field('Round type',select(Object.entries(modes),s.mode,'data-slide="mode"'))}${s.mode==='prediction'?'<p class="inline-notice">Students see the question and four choices. The picture, text, or sound stays hidden until you reveal it.</p>':''}${s.mode==='roulette'?'<p class="inline-notice">A random corner is selected each time. No correct answer is needed.</p>':''}${field('Question / instruction',`<textarea data-slide="question" rows="3" maxlength="500" placeholder="What would you like to ask?">${e(s.question)}</textarea>`)}${field('Prompt content',select([['text','Text'],['image','Picture / GIF'],['audio','Audio / listening'],['video','Video']],s.centerType,'data-slide="centerType"'))}${content}${(s.centerContent||s.graphic||s.sound)&&s.centerType!=='text'?`<div class="media-tools">${button('clear-media','Remove media','trash','small ghost')}</div>`:''}<hr class="inspector-divider">${field('After the reveal',`<textarea data-slide="explanation" rows="2" maxlength="300" placeholder="Optional explanation or follow-up">${e(s.explanation)}</textarea>`,'Shown after the correct corner is revealed.')}${s.mode!=='roulette'&&!s.corners.some(c=>c.isCorrect)?'<div class="validation-note">Choose a corner, then mark it as the correct answer.</div>':''}`;
 }else{const c=s.corners[target];el.innerHTML=`${tabs}<div class="eyebrow">Answer panel</div><h2>Corner ${target+1}</h2>${field('Answer text',`<textarea data-corner="text" rows="3" maxlength="500" placeholder="Type a choice…">${e(c.text)}</textarea>`)}<label class="field"><span>Your picture</span></label><button type="button" class="media-drop" data-action="upload">${c.image?`<img src="${e(c.image)}" alt="Current corner picture">`:c.graphic?graphic(c.graphic):`${icon('image')} Upload a picture<br>or paste from your clipboard`}</button><div class="media-tools">${button('assets','My media','folder','small')}${button('media-url','Use a URL','','small ghost')}</div>${c.image||c.graphic?`<div class="media-tools">${button('clear-media','Remove visual','trash','small ghost')}</div>`:''}<hr class="inspector-divider">${s.mode!=='roulette'?`<button type="button" class="correct-button ${c.isCorrect?'chosen':''}" data-action="correct" aria-pressed="${c.isCorrect}">${icon(c.isCorrect?'check':'plus')}${c.isCorrect?'Correct corner':'Mark as correct'}</button><p class="inspector-subtitle" style="margin-top:12px">One correct answer per round.</p>`:'<p class="inline-notice">This is a random round. Any of the four corners can be selected.</p>'}`;}}
function renderPlayer(){root.innerHTML=`<main class="player ${motionReduced()?'reduced-motion':''}"><header class="app-header"><div class="header-title">${brand()}<span class="header-divider"></span><span class="play-round-label">Round ${playIndex+1} / ${project.slides.length}</span></div><div class="header-actions">${iconButton('previous','Previous round','back',playIndex===0?'disabled':'')}${iconButton('next','Next round','chevron')}${iconButton('focus',focus?'Show corners':'Focus on the prompt','eye')}${iconButton('fullscreen','Toggle full screen','expand')}${button('exit','Studio','edit','ghost')}</div></header><div id="player-stage" style="display:contents"></div><div class="control-bar" id="controls"></div><div class="sr-only" id="round-announcement" aria-live="polite"></div></main>`;renderPlayerStage();stageMotion.enter(root.querySelector('.stage'),motionReduced(),()=>{if(view==='play')renderControls();});renderControls();}
function renderPlayerStage(){const el=document.getElementById('player-stage');if(el){el.innerHTML=stageMarkup(currentPlay(),false);scheduleFit();}}
function renderControls(){const el=document.getElementById('controls');if(!el)return;const s=currentPlay();if(!s)return;const state=engine.state;const descriptions={choose:['Choose your corner',s.mode==='prediction'?'Make your prediction. The clue stays hidden until the reveal.':hasAudio(s)?'Play the audio, then let everyone choose.':'Walk to a corner. Start the timer when the class is ready.'],counting:['Find your corner','Walk carefully. Lock in your choice before time runs out.'],paused:['Timer paused','Take your time. Resume when everyone is ready.'],locked:['Choices locked',s.mode==='roulette'?'Ready to find the lucky corner?':'Ready for the answer?'],revealing:[s.mode==='roulette'?'Selecting a corner…':'Here comes the answer…',''],revealed:[resultText(project,s,engine.winner??0),s.explanation|| (project.rules==='out'?'Students in the selected corner step out for this game.':project.rules==='safe'?'Students in the selected corner stay in.':'Everyone can join the next round.')]};const [title,sub]=descriptions[state]||descriptions.choose;
 let controls='';if(state==='choose')controls=button('reveal',s.mode==='roulette'?'Spin now':'Reveal now','','ghost',stageMotion.entering?'disabled':'')+button('start-timer',`Start ${project.settings.seconds}s timer`,'clock','primary',stageMotion.entering?'disabled':'');if(state==='counting')controls=button('reveal','Reveal now','','ghost')+button('pause','Pause','pause','primary');if(state==='paused')controls=button('replay-round','Reset timer','','ghost')+button('start-timer','Resume','play','primary');if(state==='locked')controls=button('reveal',s.mode==='roulette'?'Select a corner':'Reveal answer',s.mode==='roulette'?'shuffle':'spark','primary');if(state==='revealing')controls=button('noop','A little suspense…','','primary','disabled');if(state==='revealed')controls=button('replay-round','Replay round','','ghost')+button('next',playIndex===project.slides.length-1?'Finish game':'Next round','chevron','primary');
 const time=['counting','paused'].includes(state)?Math.ceil(engine.remaining/1000):state==='choose'?project.settings.seconds:0;const ratio=['counting','paused'].includes(state)?engine.remaining/(project.settings.seconds*1000):state==='choose'?1:0;
 updateClock(time,ratio,state);
 el.innerHTML=`<div class="play-status"><div class="play-status-copy"><strong class="${state==='revealed'?'result-title':''}">${e(title)}</strong><small>${e(sub)}</small></div></div><div class="play-buttons">${controls}</div>`;const live=document.getElementById('round-announcement');if(live)live.textContent=title;}
async function launch(index=0){sound.configure(project.settings);const errors=validateProject(project);if(errors.length){selected=errors[0].index;target='prompt';view='edit';renderEditor();showValidation(errors);return;}await persist();sound.stopAll();await sound.unlock();view='play';focus=false;playIndex=index;engine.load(currentPlay(),{...project.settings,reducedMotion:motionReduced()});renderPlayer();}
function loadRound(index){if(index<0)return;if(index>=project.slides.length){finish();return;}sound.stopAll();stopVideo();playingAudio=false;playIndex=index;focus=false;engine.load(currentPlay(),{...project.settings,reducedMotion:motionReduced()});renderPlayer();}
function finish(){stageMotion.cancel();sound.stopAll();engine.stop();view='finish';root.innerHTML=`<main class="player"><header class="app-header">${brand()}${button('exit','Back to studio','edit','ghost')}</header><section class="celebration"><div class="trophy">${icon('spark')}</div><div class="eyebrow">${e(project.name)}</div><h1>Well played, everyone!</h1><p>${project.slides.length} rounds of listening, thinking, and moving.<br>Thanks for playing Four Corners.</p><div class="row wrap">${button('play-again','Play again','play','primary')}${button('home','Choose another game','home')}</div><p class="credit">Created by Drew Wichman</p></section></main>`;sound.effect('end');}

function stopVideo(){root.querySelectorAll('video').forEach(v=>v.pause());}
function playCue(){if(playingAudio){sound.stopMusic();return;}const s=view==='play'?currentPlay():current();if(!hasAudio(s))return;if(view==='play'&&s.mode==='prediction'&&engine.state!=='revealed')return;playingAudio=true;updateCueUI();sound.play(s,()=>{playingAudio=false;updateCueUI();});}
function updateCueUI(){root.querySelectorAll('[data-action="cue"]').forEach(b=>{b.classList.toggle('is-playing',playingAudio);b.querySelector('span:last-child').textContent=playingAudio?'Stop audio':'Play audio';});const btn=root.querySelector('[data-action="editor-cue"]');if(btn)btn.innerHTML=icon(playingAudio?'stop':'play')+`<span>${playingAudio?'Stop':'Listen'}</span>`;}
function openModal(title,body,footer='',kind=''){modalKind=kind;modal.innerHTML=`<div class="dialog-head"><h2>${title}</h2>${iconButton('close-modal','Close dialog','close')}</div><div class="dialog-body">${body}</div>${footer?`<div class="dialog-footer">${footer}</div>`:''}`;if(!modal.open)modal.showModal();}
function showValidation(errors){openModal('A quick check before playing',`<p class="dialog-copy">These rounds need a little more information.</p><div class="stack">${errors.slice(0,12).map(err=>button('fix-round',e(err.message),'edit','',`data-index="${err.index}"`)).join('')}</div>`,button('close-modal','Back to editing','','primary'));}
function showSettings(){const s=project.settings;openModal('Game settings',`<div class="settings-grid">${field('What happens to the selected corner?',select([['all','Everyone plays — reveal only'],['safe','Selected corner stays in'],['out','Selected corner is out']],project.rules,'data-project="rules"')).replace('class="field"','class="field full"')}${field('Corner labels',select(Object.keys(LABELS).map(k=>[k,k[0].toUpperCase()+k.slice(1)]),project.labels,'data-project="labels"'))}${field('Countdown (seconds)',`<input type="number" data-setting="seconds" min="3" max="120" value="${s.seconds}">`)}${field('Suspense before reveal',select([['0','Instant'],['1','Short — 1 second'],['2.5','Standard — 2.5 seconds'],['4','Dramatic — 4 seconds']],String(s.suspense),'data-setting="suspense"'))}${field(`Listening volume <output id="musicVolume-value">${Math.round(s.musicVolume*100)}%</output>`,`<input type="range" min="0" max="1" step=".05" value="${s.musicVolume}" data-setting="musicVolume">`)}${field(`Effects volume <output id="effectsVolume-value">${Math.round(s.effectsVolume*100)}%</output>`,`<input type="range" min="0" max="1" step=".05" value="${s.effectsVolume}" data-setting="effectsVolume">`)}<div class="full stack"><label class="checkline"><input type="checkbox" data-setting="autoReveal" ${s.autoReveal?'checked':''}><span>Reveal automatically after the timer<small>Turn off to wait for your cue.</small></span></label><label class="checkline"><input type="checkbox" data-setting="largeText" ${s.largeText?'checked':''}><span>Extra-large text</span></label><label class="checkline"><input type="checkbox" data-setting="reducedMotion" ${s.reducedMotion?'checked':''}><span>Gentle motion<small>Skip entrances and reveal immediately.</small></span></label></div></div><hr class="inspector-divider"><h3 style="font-size:16px;margin-bottom:5px">Your sound effects</h3>${[['countdown','Countdown'],['drumroll','Suspense'],['happy','Correct / safe'],['sad','Eliminated']].map(([key,name])=>`<div class="audio-cue-row"><span><strong>${name}</strong><small>${key==='countdown'&&project.audio.countdownVariations?.length?project.audio.countdownVariations.length+' rotating tracks':project.audio[key]?'Custom audio':'Built-in sound'}</small></span><div class="row">${iconButton('preview-effect','Preview '+name,'play',`data-key="${key}"`)}${button('upload-effect','Replace','','small',`data-key="${key}"`)}${(project.audio[key]||(key==='countdown'&&project.audio.countdownVariations?.length))?iconButton('clear-effect','Reset to built-in','close',`data-key="${key}"`):''}</div></div>`).join('')}<p class="dialog-copy" style="margin:18px 0 0">Choose several countdown audio files to rotate music each round. Your games save on this browser. Export a .4cr file to back them up or use them on another device.</p>`,button('close-modal','Done','check','primary'),'settings');}
function showHelp(){openModal('Let’s play Four Corners',`<div class="help-step"><b>1</b><div><h3>Give each corner a home.</h3><p>Place signs 1–4 around your room. You can print matching signs from the studio.</p></div></div><div class="help-step"><b>2</b><div><h3>Look, listen, and choose.</h3><p>Display a question or play an audio clip. Students walk to the matching corner. For mystery rounds, they choose before the hidden clue is revealed.</p></div></div><div class="help-step"><b>3</b><div><h3>Start the countdown.</h3><p>Pause whenever you need. When time runs out, choices lock. You decide when to reveal, unless automatic reveal is enabled.</p></div></div><div class="help-step"><b>4</b><div><h3>Reveal and play again.</h3><p>Keep everyone playing, keep only the selected corner in, or eliminate the selected corner. Change this in Game settings.</p></div></div><hr class="inspector-divider"><h3>Teacher shortcuts</h3><div class="shortcut-list"><div><kbd>Space</kbd> Start / pause / next</div><div><kbd>R</kbd> Reveal</div><div><kbd>← →</kbd> Change rounds</div><div><kbd>A</kbd> Play / stop audio</div><div><kbd>F</kbd> Full screen</div><div><kbd>Esc</kbd> Close a dialog</div></div>`,button('close-modal','Got it','check','primary'));}
function openAssets(tab='instrument',specificTarget=target){assetTab=tab;assetTarget=specificTarget;renderAssets();}
function renderAssets(){const cards=project.assets.filter(a=>assetTarget==='prompt'||a.type==='image').map(a=>`<button type="button" class="asset-card" data-action="choose-asset" data-id="${e(a.id)}">${a.type==='image'?`<img src="${e(a.src)}" alt="${e(a.name)}">`:icon(a.type==='audio'?'headphones':'play')}<span>${e(a.name)}</span></button>`).join('');openModal('My uploaded media',`<div class="asset-grid">${cards||'<div class="empty-assets">No uploaded media yet.<br>Add your own pictures, audio, or video.</div>'}</div>`,button('upload-from-assets','Upload media','plus')+button('close-modal','Done','','primary'),'assets');}
function showExport(){openModal('Export your game',`<div class="stack"><h3>Standalone game · HTML</h3><p class="dialog-copy">A player-only file for your buyers. Includes the rounds, timer, reveals, and used media. Opens in a desktop browser without the studio, a sign-in, or an internet connection. It contains no game editor.</p>${field('Creator / store credit (optional)',`<input id="export-author" maxlength="120" value="${e(project.author??'Drew Wichman')}" placeholder="Your name or store">`)}${button('export-standalone','Prepare standalone game','save','primary')}<hr><h3>Editable backup · .4cr</h3><p class="dialog-copy">Keep this file for future edits or moving the project to another device. It opens in Four Corners Studio.</p>${button('export-backup','Download editable backup','save')}</div>`,button('close-modal','Close'))}
function exportGame(){const data=JSON.stringify({...project,version:2});const blob=new Blob([data],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=(project.name.replace(/[^a-z0-9 _-]/gi,'').trim()||'four-corners')+'.4cr';(document.querySelector('dialog[open]')||document.body).append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000);toast('Game exported, including uploaded pictures and audio.');}
function printSigns(){const colors=cornerColors(project);document.getElementById('print-area').innerHTML=labelsFor(project).map((label,i)=>`<section class="print-sign"><h1>CORNER ${i+1}</h1><div class="print-number">${e(label)}</div><div class="print-color" style="--sign-color:${colors[i]}"></div><p>Mr. Drew’s Four Corners · Created by Drew Wichman</p></section>`).join('');window.print();}
function undo(redo=false){const from=redo?redoStack:undoStack,to=redo?undoStack:redoStack;if(!from.length)return;to.push(clone(project));project=from.pop();selected=Math.min(selected,project.slides.length-1);changed();renderEditor();}
function upload(targetOverride=target){assetTarget=targetOverride;const input=document.getElementById('media-file');input.accept=assetTarget==='prompt'?'image/*,audio/*,video/*':'image/*';input.click();}
async function applyUpload(file){if(!file)return;try{toast('Adding media…');const projectId=project.id,slideId=current().id,to=assetTarget;const src=await mediaData(file);if(project.id!==projectId||current().id!==slideId){toast('The round changed. Please add the file again.');return;}if(to!=='prompt'&&!file.type.startsWith('image/'))throw new Error('Corner panels use pictures. Add audio to the prompt.');remember();const type=file.type.split('/')[0];const asset={id:uid(),name:file.name,type,src};project.assets.push(asset);if(to==='prompt'){const s=current();s.centerType=type;s.centerContent=src;s.graphic=null;s.sound=null;s.clip={start:0,end:0};}else{current().corners[to].image=src;current().corners[to].graphic=null;}target=to;changed();modal.close();renderEditorPreview();renderInspector();toast('Media added.');}catch(err){toast(err.message||'The file could not be added.');}}
async function fullScreen(){try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{toast('Use your browser’s full-screen option on this device.');}}

document.addEventListener('click',async ev=>{const b=ev.target.closest('[data-action]');if(!b||b.disabled)return;const action=b.dataset.action;
 switch(action){
 case'home':goHome();break;
 case'help':showHelp();break;
 case'new':if(view!=='home')await persist();openProject(newProject());break;
 case'recent':{const r=recent.find(r=>r.id===b.dataset.id);if(r)openProject(normalizeProject(r.project));break;}
 case'delete-saved':{const r=recent.find(r=>r.id===b.dataset.id);openModal('Delete this saved game?',`<p class="dialog-copy">Remove “${e(r?.name)}” from this browser? Exported .4cr files will still work.</p>`,button('close-modal','Keep game')+button('confirm-delete-saved','Delete saved game','trash','danger',`data-id="${e(b.dataset.id)}"`));break;}
 case'confirm-delete-saved':try{await deleteProject(b.dataset.id);modal.close();await loadRecent();}catch{toast('The saved game could not be deleted.');}break;
 case'import':document.getElementById('game-file').click();break;
 case'export':showExport();break;
 case'export-backup':exportGame();break;
 case'export-standalone':{const errors=validateProject(project);if(errors.length){showValidation(errors);break;}b.disabled=true;try{project.author=document.getElementById('export-author').value.trim();changed();await exportStandalone(clone(project));toast('Your game is ready. Choose Save standalone game to download it.');}catch(err){toast(err.message||'Export failed. Please try again.');}finally{b.disabled=false;}break;}
 case'play':case'play-again':launch(0);break;
 case'preview-round':launch(selected);break;
 case'exit':stageMotion.cancel();engine.stop();sound.stopAll();stopVideo();playingAudio=false;view='edit';selected=playIndex;renderEditor();break;
 case'target':target=b.dataset.target==='prompt'?'prompt':Number(b.dataset.target);renderEditorPreview();renderInspector();break;
 case'select-round':sound.stopAll();playingAudio=false;selected=Number(b.dataset.index);target='prompt';renderEditor();break;
 case'fix-round':selected=Number(b.dataset.index);target='prompt';modal.close();renderEditor();break;
 case'add':if(project.slides.length>=300){toast('This game has reached 300 rounds. Start a new game for more.');break;}remember();project.slides.splice(selected+1,0,newSlide());selected++;target='prompt';changed();renderEditor();break;
 case'duplicate':if(project.slides.length>=300)break;remember();{const s=clone(current());s.id=uid();project.slides.splice(selected+1,0,s);selected++;target='prompt';changed();renderEditor();}break;
 case'delete-round':if(project.slides.length===1){toast('Keep at least one round in the game.');break;}remember();project.slides.splice(selected,1);selected=Math.min(selected,project.slides.length-1);target='prompt';changed();renderEditor();toast('Round deleted. Use Undo to restore it.');break;
 case'move-up':case'move-down':{const next=selected+(action==='move-up'?-1:1);if(next<0||next>=project.slides.length)break;remember();[project.slides[selected],project.slides[next]]=[project.slides[next],project.slides[selected]];selected=next;changed();renderEditor();break;}
 case'shuffle':remember();project.slides=shuffled(project.slides);selected=0;target='prompt';changed();renderEditor();break;
 case'undo':undo();break;
 case'redo':undo(true);break;
 case'correct':remember();current().corners.forEach((c,i)=>c.isCorrect=i===target);changed();renderInspector();break;
 case'settings':showSettings();break;
 case'assets':openAssets('library');break;
 case'choose-asset':{const a=project.assets.find(a=>a.id===b.dataset.id);if(!a)break;remember();if(assetTarget==='prompt'){Object.assign(current(),{centerType:a.type,centerContent:a.src,graphic:null,sound:null,clip:{start:0,end:0}});}else{Object.assign(current().corners[assetTarget],{image:a.src,graphic:null});}target=assetTarget;changed();modal.close();renderEditorPreview();renderInspector();break;}
 case'upload':upload();break;
 case'upload-from-assets':upload(assetTarget);break;
 case'clear-media':remember();sound.stopMusic();if(target==='prompt'){Object.assign(current(),{centerContent:'',graphic:null,sound:null,clip:{start:0,end:0}});}else{current().corners[target].image='';current().corners[target].graphic=null;}changed();renderEditorPreview();renderInspector();break;
 case'media-url':openModal('Use a media URL',`${field('Direct image or audio URL','<input id="media-url-input" type="url" placeholder="https://…">')}<p class="dialog-copy">Uploaded files travel with your game. Linked media needs an internet connection and an accessible URL.</p>`,button('close-modal','Cancel')+button('apply-url','Use media','','primary'));break;
 case'apply-url':{const src=document.getElementById('media-url-input').value.trim();if(!/^https?:\/\//.test(src)||!safeMedia(src)){toast('Enter a direct https:// image or audio URL.');break;}remember();if(target==='prompt'){current().centerContent=src;if(!['image','audio','video'].includes(current().centerType))current().centerType='image';current().graphic=null;current().sound=null;}else{current().corners[target].image=src;current().corners[target].graphic=null;}changed();modal.close();renderEditorPreview();renderInspector();break;}
 case'upload-effect':pendingCue=b.dataset.key;document.getElementById('cue-file').multiple=pendingCue==='countdown';document.getElementById('cue-file').click();break;
 case'clear-effect':remember();project.audio[b.dataset.key]=null;if(b.dataset.key==='countdown')delete project.audio.countdownVariations;changed();showSettings();break;
 case'preview-effect':await sound.unlock();sound.configure(project.settings);sound.stopEffects();if(b.dataset.key==='countdown'&&countdownSource(project,selected))sound.custom(countdownSource(project,selected));else if(project.audio[b.dataset.key])sound.custom(project.audio[b.dataset.key]);else sound.effect({countdown:'tick',drumroll:'suspense',happy:'safe',sad:'out'}[b.dataset.key]);break;
 case'print':printSigns();break;
 case'close-modal':modal.close();sound.stopEffects();break;
 case'cue':case'editor-cue':sound.configure(project.settings);playCue();break;
 case'start-timer':if(stageMotion.entering)break;sound.configure(project.settings);playingAudio=false;updateCueUI();stopVideo();await sound.startCountdown(engine,countdownSource(project,playIndex));break;
 case'pause':engine.pause();break;
 case'reveal':{if(stageMotion.entering)break;const epoch=engine.epoch;sound.stopAll();await sound.unlock();if(view!=='play'||engine.epoch!==epoch)break;sound.configure(project.settings);playingAudio=false;updateCueUI();stopVideo();focus=false;root.querySelector('.stage')?.classList.remove('focus-prompt');engine.reveal();break;}
 case'previous':loadRound(playIndex-1);break;
 case'next':loadRound(playIndex+1);break;
 case'replay-round':loadRound(playIndex);break;
 case'focus':stageMotion.cancel();renderControls();focus=!focus;root.querySelector('.stage')?.classList.toggle('focus-prompt',focus);b.setAttribute('aria-label',focus?'Show corners':'Focus on the prompt');scheduleFit();break;
 case'fullscreen':fullScreen();break;
 }
});
function formUpdate(el,finished=false){
 if(el.dataset.project){const key=el.dataset.project;project[key]=el.value;if(key==='name')project.name=el.value.slice(0,120);changed();if(key!=='name')renderEditorPreview();return;}
 if(el.dataset.setting){const key=el.dataset.setting;project.settings[key]=el.type==='checkbox'?el.checked:['seconds','suspense','musicVolume','effectsVolume'].includes(key)?Number(el.value):el.value;if(finished&&key==='seconds'){project.settings.seconds=Math.min(120,Math.max(3,Math.round(Number(el.value)||10)));el.value=project.settings.seconds;}if(key==='musicVolume'||key==='effectsVolume'){const out=document.getElementById(key+'-value');if(out)out.textContent=Math.round(project.settings[key]*100)+'%';}sound.configure(project.settings);changed();renderEditorPreview();return;}
 if(view!=='edit')return;
 if(el.dataset.slide){const key=el.dataset.slide;if(key==='centerType'&&current().centerType!==el.value){sound.stopMusic();Object.assign(current(),{centerContent:'',graphic:null,sound:null,clip:{start:0,end:0}});}current()[key]=el.value;changed();renderEditorPreview();renderRail();if(key==='mode'||key==='centerType')renderInspector();}
 if(el.dataset.corner){current().corners[target][el.dataset.corner]=el.value;changed();renderEditorPreview();}
 if(el.dataset.clip){current().clip[el.dataset.clip]=Math.max(0,Number(el.value)||0);changed();}
 if(el.dataset.sound){if(current().sound){current().sound.tempo=Math.min(200,Math.max(40,Number(el.value)||100));changed();}}
}
document.addEventListener('focusin',ev=>{if(ev.target.matches('[data-slide],[data-corner],[data-setting],[data-project],[data-clip],[data-sound]'))remember();});
document.addEventListener('input',ev=>{const el=ev.target;if(el.matches('input:not([type=file]),textarea'))formUpdate(el);});
document.addEventListener('change',ev=>{if(ev.target.matches('select,input:not([type=file])'))formUpdate(ev.target,true);});
document.addEventListener('keydown',ev=>{if(modal.open)return;const typing=ev.target.matches('input,textarea,select,[contenteditable=true]');if(view==='edit'&&!typing&&(ev.ctrlKey||ev.metaKey)&&ev.key.toLowerCase()==='z'){ev.preventDefault();undo(ev.shiftKey);return;}if(typing)return;if(ev.key==='Enter'&&ev.target.matches('[role=button][data-action]')){ev.preventDefault();ev.target.click();return;}if(view!=='play')return;if(ev.target.closest('button')&&['Space','Enter'].includes(ev.code))return;let action=null;if(ev.code==='Space'){action=engine.state==='choose'||engine.state==='paused'?'start-timer':engine.state==='counting'?'pause':engine.state==='locked'?'reveal':engine.state==='revealed'?'next':null;}if(ev.key.toLowerCase()==='r')action='reveal';if(ev.key.toLowerCase()==='a')action='cue';if(ev.key.toLowerCase()==='f')action='fullscreen';if(ev.key==='ArrowLeft')action='previous';if(ev.key==='ArrowRight')action='next';if(action){ev.preventDefault();const el=root.querySelector(`[data-action="${action}"]`);el?.click();}});
document.addEventListener('dragstart',ev=>{const thumb=ev.target.closest('.slide-thumb');if(!thumb)return;dragIndex=Number(thumb.dataset.index);ev.dataTransfer.effectAllowed='move';ev.dataTransfer.setData('text/plain',String(dragIndex));});
document.addEventListener('dragover',ev=>{const thumb=ev.target.closest('.slide-thumb');if(thumb&&dragIndex>=0){ev.preventDefault();thumb.classList.add('drag-over');}});
document.addEventListener('dragleave',ev=>ev.target.closest('.slide-thumb')?.classList.remove('drag-over'));
document.addEventListener('drop',ev=>{const thumb=ev.target.closest('.slide-thumb');if(!thumb||dragIndex<0)return;ev.preventDefault();const to=Number(thumb.dataset.index);remember();const [s]=project.slides.splice(dragIndex,1);project.slides.splice(to,0,s);selected=to;dragIndex=-1;target='prompt';changed();renderEditor();});
document.addEventListener('dragend',()=>{dragIndex=-1;root.querySelectorAll('.drag-over').forEach(e=>e.classList.remove('drag-over'));});
document.addEventListener('paste',ev=>{if(view!=='edit'||modal.open)return;const file=Array.from(ev.clipboardData?.files||[]).find(f=>f.type.startsWith('image/'));if(file){ev.preventDefault();assetTarget=target;applyUpload(file);}});
document.getElementById('game-file').addEventListener('change',async ev=>{const file=ev.target.files[0];ev.target.value='';if(!file)return;try{if(file.size>100*1024*1024)throw new Error('Choose a .4cr file smaller than 100 MB.');const parsed=normalizeProject(JSON.parse(await file.text()));if(view!=='home')await persist();parsed.id=uid();openProject(parsed);toast('Game imported. Your original file is unchanged.');}catch(err){toast(err instanceof SyntaxError?'This file is not a readable .4cr game.':err.message);}});
document.getElementById('media-file').addEventListener('change',ev=>{const f=ev.target.files[0];ev.target.value='';applyUpload(f);});
document.getElementById('cue-file').addEventListener('change',async ev=>{const files=Array.from(ev.target.files);ev.target.value='';if(!files.length)return;const key=pendingCue,id=project.id;try{if(files.some(f=>!f.type.startsWith('audio/')))throw new Error('Choose audio files.');if(files.length>12)throw new Error('Choose up to 12 countdown tracks.');const clips=await Promise.all(files.map(mediaData));if(project.id!==id)return;remember();project.audio[key]=clips[0];if(key==='countdown'){if(clips.length>1)project.audio.countdownVariations=clips;else delete project.audio.countdownVariations;}changed();showSettings();}catch(err){toast(err.message);}});
window.addEventListener('beforeunload',ev=>{if(unsaved){persist();ev.preventDefault();ev.returnValue='';}});
document.addEventListener('visibilitychange',()=>{if(document.hidden){if(unsaved)persist();if(engine.state==='counting')engine.pause();sound.stopAll();stopVideo();}});
modal.addEventListener('click',ev=>{if(ev.target===modal){const r=modal.getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)modal.close();}});
modal.addEventListener('close',()=>{modalKind='';sound.stopEffects();});
renderHome();loadRecent();
